import{_ as a,a0 as n,w as p,s as r,ao as l,I as o,x as e,a1 as i,A as d}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse('{"title":"Linux 中退出碼的含義 | LCTT x X-CMD","titleTemplate":false,"description":"Linux 中退出碼的含義 | LCTT (202308) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux 中退出碼的含義 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux 中退出碼的含義 | LCTT (202308) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202308/20230709.0 ⭐️⭐️ What are Exit Codes in Linux","title":"Linux 中退出碼的含義","tag":"202308","desc":""},"relativePath":"202308/20230709.0 ⭐️⭐️ What are Exit Codes in Linux.md","filePath":"[post].md"}'),c={name:"202308/20230709.0 ⭐️⭐️ What are Exit Codes in Linux.md"};function g(m,t,u,h,f,x){const s=n("Link");return p(),r("div",null,[t[44]||(t[44]=l('<h1 id="linux-中退出碼的含義" tabindex="-1">Linux 中退出碼的含義 <a class="header-anchor" href="#linux-中退出碼的含義" aria-label="Permalink to “Linux 中退出碼的含義”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202308/03/154628oloxp7sl6s1z4pbl.jpg" alt=""></p><blockquote><p>揭開 Linux 中退出碼的神秘面紗。瞭解什麼是退出碼，以及為什麼和如何使用它們。</p></blockquote><p>退出碼（退出狀態）可以告訴我們最後一次執行的命令的狀態。在命令結束以後，我們可以知道命令是成功完成的還是以錯誤結束的。</p><p><strong>其基本思想是，程序返回退出代碼 <code>0</code> 時表示執行成功，沒有問題。代碼 <code>1</code> 或 <code>0</code> 以外的任何代碼都被視為不成功。</strong></p><p>退出碼除了 0 和 1 外還有很多值，我將在本文介紹它們。</p><h3 id="linux-shell-中的各種退出碼" tabindex="-1">Linux Shell 中的各種退出碼 <a class="header-anchor" href="#linux-shell-中的各種退出碼" aria-label="Permalink to “Linux Shell 中的各種退出碼”">​</a></h3><p>我們來快速瞭解一下 Linux Shell 中的主要退出碼：</p><div class="table-wrap"><table><thead><tr><th style="text-align:left;">退出碼</th><th style="text-align:left;">解釋</th></tr></thead><tbody><tr><td style="text-align:left;"><code>0</code></td><td style="text-align:left;">命令成功執行</td></tr><tr><td style="text-align:left;"><code>1</code></td><td style="text-align:left;">通用錯誤代碼</td></tr><tr><td style="text-align:left;"><code>2</code></td><td style="text-align:left;">命令（或參數）使用不當</td></tr><tr><td style="text-align:left;"><code>126</code></td><td style="text-align:left;">權限被拒絕（或）無法執行</td></tr><tr><td style="text-align:left;"><code>127</code></td><td style="text-align:left;">未找到命令，或 <code>PATH</code> 錯誤</td></tr><tr><td style="text-align:left;"><code>128+n</code></td><td style="text-align:left;">命令被信號從外部終止，或遇到致命錯誤</td></tr><tr><td style="text-align:left;"><code>130</code></td><td style="text-align:left;">通過 <code>Ctrl+C</code> 或 <code>SIGINT</code> 終止（<em>終止代碼 2 或鍵盤中斷</em>）</td></tr><tr><td style="text-align:left;"><code>143</code></td><td style="text-align:left;">通過 <code>SIGTERM</code> 終止（<em>默認終止</em>）</td></tr><tr><td style="text-align:left;"><code>255/*</code></td><td style="text-align:left;">退出碼超過了 0-255 的範圍，因此重新計算（LCTT 譯註：超過 255 後，用退出碼對 256 取模）</td></tr></tbody></table></div><blockquote><p>📋 <code>130</code>（<code>SIGINT</code> 或 <code>^C</code>）和 <code>143</code>（<code>SIGTERM</code>）等終止信號是非常典型的，它們屬於 <code>128+n</code> 信號，其中 <code>n</code> 代表終止碼。</p></blockquote><p>在簡單瞭解了退出碼之後，我們來看看它們的用法。</p><h3 id="獲取退出碼" tabindex="-1">獲取退出碼 <a class="header-anchor" href="#獲取退出碼" aria-label="Permalink to “獲取退出碼”">​</a></h3>',12)),o("p",null,[t[1]||(t[1]=e("前一個命令執行的退出碼存儲在 ",-1)),i(s,{href:"https://linuxhandbook.com:443/bash-special-variables/"},{default:d(()=>[...t[0]||(t[0]=[e("特殊變量",-1)])]),_:1}),t[2]||(t[2]=e()),t[3]||(t[3]=o("code",null,"$?",-1)),t[4]||(t[4]=e(" 中。你可以通過運行以下命令來獲取：",-1))]),t[45]||(t[45]=l(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>echo $?</span></span></code></pre></div><p>我們在所有演示中都將使用它來獲取退出代碼。</p><p>請注意，<code>exit</code> 命令支持以帶着前一條命令相同的退出碼退出。</p><h3 id="退出碼-0" tabindex="-1">退出碼 0 <a class="header-anchor" href="#退出碼-0" aria-label="Permalink to “退出碼 0”">​</a></h3><p>退出碼 <code>0</code> 表示命令執行無誤，這是完成命令的理想狀態。</p><p>例如，我們運行這樣一條基本命令</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>neofetch </span></span>
<span class="line"><span></span></span>
<span class="line"><span>echo $?</span></span></code></pre></div><p><img src="https://itsfoss.com/content/images/2023/06/exit_code_0.png" alt=""></p><p>這個退出碼 <code>0</code> 表示特定命令已成功執行，僅此而已。讓我們再演示幾個例子。</p>`,9)),o("p",null,[t[6]||(t[6]=e("你可以嘗試 ",-1)),i(s,{href:"https://itsfoss.com/how-to-find-the-process-id-of-a-program-and-kill-it-quick-tip/"},{default:d(()=>[...t[5]||(t[5]=[e("終止一個進程",-1)])]),_:1}),t[7]||(t[7]=e("；它也會返回代碼 ",-1)),t[8]||(t[8]=o("code",null,"0",-1)),t[9]||(t[9]=e("。",-1))]),t[46]||(t[46]=l('<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>pkill lxappearance</span></span></code></pre></div><p><img src="https://itsfoss.com/content/images/2023/06/exit_code_0.gif" alt=""></p><p>查看文件內容也會返回退出碼 0，這<strong>僅</strong>意味着 <code>cat</code> 命令執行成功。</p><h3 id="退出碼-1" tabindex="-1">退出碼 1 <a class="header-anchor" href="#退出碼-1" aria-label="Permalink to “退出碼 1”">​</a></h3><p>退出碼 <code>1</code> 也很常見。它通常表示命令以一般錯誤結束。</p>',5)),o("p",null,[t[11]||(t[11]=e("例如，在沒有 sudo 權限的情況下使用 ",-1)),i(s,{href:"https://itsfoss.com/package-manager/"},{default:d(()=>[...t[10]||(t[10]=[e("軟件包管理器",-1)])]),_:1}),t[12]||(t[12]=e("，就會返回代碼 ",-1)),t[13]||(t[13]=o("code",null,"1",-1)),t[14]||(t[14]=e("。在 Arch Linux 中，如果我運行下面的命令：",-1))]),t[47]||(t[47]=l('<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>pacman -Sy</span></span></code></pre></div><p>它會返回 <code>1</code>， 表示上一條命令運行出錯。</p><p><img src="https://itsfoss.com/content/images/2023/06/exit_code_1.png" alt="exit code 1 (impermissible operation resulted in this code)"></p><blockquote><p>📋 如果你在基於 Ubuntu 的發行版中嘗試這樣做（不使用 <code>sudo</code> 執行 <code>apt update</code>），運行後會得到錯誤碼 <code>100</code>，表示你是在沒有權限的情況下運行 <code>apt</code>。<code>100</code> 不是標準錯誤碼，而是 <code>apt</code> 特有的錯誤碼。</p></blockquote><p>雖然這是一般的理解，但我們也可以將其解釋為 “不被允許的操作”。</p><p>除以 <code>0</code> 等操作也會返回錯誤碼 <code>1</code>。</p><p><img src="https://itsfoss.com/content/images/2023/06/exit_code_1-division_by_0-.png" alt="Division by zero results in code 1"></p><h3 id="退出碼-2" tabindex="-1">退出碼 2 <a class="header-anchor" href="#退出碼-2" aria-label="Permalink to “退出碼 2”">​</a></h3><p>這個退出碼出現在當執行的命令有語法錯誤時。濫用命令參數也會導致此錯誤。</p><p>一般來説，它表示由於使用不當，命令無法執行。</p><p>例如，我在一個本應只有一個連字符的選項上添加了兩個連字符，那麼此時會出現退出碼 2。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>grep --z file.txt</span></span></code></pre></div><p><img src="https://itsfoss.com/content/images/2023/06/exit_status_2-misusing_arguments--1.png" alt="Invalid argument resulted in exit code 2"></p><p>當權限被拒絕時，比如訪問 <code>/root</code> 文件夾，就會出現錯誤碼 <code>2</code>。</p><p><img src="https://itsfoss.com/content/images/2023/06/exit_code_2-permission_denied-.png" alt="Permission denied gives out code 2"></p><h3 id="退出碼-126" tabindex="-1">退出碼 126 <a class="header-anchor" href="#退出碼-126" aria-label="Permalink to “退出碼 126”">​</a></h3><p>126 是一個特殊的退出碼，它用於表示命令或腳本因權限錯誤而未被執行。</p><p>當你嘗試執行沒有執行權限的 Shell 腳本時，就會出現這個錯誤。</p><p><img src="https://itsfoss.com/content/images/2023/06/exit_code_126.png" alt=""></p><p>請注意，該退出碼只出現在沒有足夠權限的腳本或命令的“<em>執行</em>”中，這與一般的<strong>權限被拒絕</strong>錯誤不同。</p><p>因此，不要把它與你之前看到的退出碼為 <code>2</code> 的示例混淆。在那個示例中，運行的是 <code>ls</code> 命令，權限問題出自它試圖執行的目錄。而本例中權限問題來自腳本本身。</p><h3 id="退出碼-127" tabindex="-1">退出碼 127 <a class="header-anchor" href="#退出碼-127" aria-label="Permalink to “退出碼 127”">​</a></h3>',22)),o("p",null,[t[16]||(t[16]=e("這是另一個常見的退出碼。退出碼 ",-1)),t[17]||(t[17]=o("code",null,"127",-1)),t[18]||(t[18]=e(" 指的是“",-1)),i(s,{href:"https://itsfoss.com/bash-command-not-found/"},{default:d(()=>[...t[15]||(t[15]=[e("未找到命令",-1)])]),_:1}),t[19]||(t[19]=e("”。它通常發生在執行的命令有錯別字或所需的可執行文件不在 ",-1)),t[20]||(t[20]=o("code",null,"$PATH",-1)),t[21]||(t[21]=e(" 變量中時。",-1))]),t[48]||(t[48]=o("p",null,"例如，當我嘗試執行一個不帶路徑的腳本時，經常會看到這個錯誤。",-1)),t[49]||(t[49]=o("p",null,[o("img",{src:"https://itsfoss.com/content/images/2023/06/exit_code_127.png",alt:'Script executed without the path gives "command not found" or code 127'})],-1)),o("p",null,[t[23]||(t[23]=e("當你想運行的可執行文件不在 ",-1)),t[24]||(t[24]=o("code",null,"$PATH",-1)),t[25]||(t[25]=e(" 變量中時，也會出現退出碼 ",-1)),t[26]||(t[26]=o("code",null,"127",-1)),t[27]||(t[27]=e("。你可以通過 ",-1)),i(s,{href:"https://itsfoss.com/add-directory-to-path-linux/"},{default:d(()=>[...t[22]||(t[22]=[e("在 PATH 變量中添加命令的目錄",-1)])]),_:1}),t[28]||(t[28]=e(" 來糾正這種情況。",-1))]),t[50]||(t[50]=l('<p>當你輸入不存在的命令時，也會得到這樣的退出碼。</p><p><img src="https://itsfoss.com/content/images/2023/06/exit_code_127-command_not_found--1.png" alt="Unmount is not a command, and Screenfetch is not installed, which resulted in code 127"></p><h3 id="退出碼-128-n-系列" tabindex="-1">退出碼 128+n 系列 <a class="header-anchor" href="#退出碼-128-n-系列" aria-label="Permalink to “退出碼 128+n 系列”">​</a></h3><p>當應用程序或命令因致命錯誤而終止或執行失敗時，將產生 128 系列退出碼（<code>128+n</code>），其中 <code>n</code> 為信號編號。</p><p><code>n</code> 包括所有類型的終止代碼，如 <code>SIGTERM</code>、<code>SIGKILL</code> 等。</p><h4 id="退出碼-130-或-sigint" tabindex="-1">退出碼 130 或 SIGINT <a class="header-anchor" href="#退出碼-130-或-sigint" aria-label="Permalink to “退出碼 130 或 SIGINT”">​</a></h4><p>在通過終止信號 <code>2</code> 或按下 <code>Ctrl+C</code> 中斷進程時，會發出 <code>SIGINT</code>（鍵盤中斷信號）。</p><p>因為終止信號是 <code>2</code>，所以我們得到的退出碼是 <code>130</code>（128+2）。下面的視頻演示了 <code>lxappearance</code> 的中斷信號。</p><p><img src="https://itsfoss.com/content/media/2023/06/exit_code_128-n-SIGINT-_compressed.mp4" alt=""></p><h4 id="退出碼-137-或-sigkill" tabindex="-1">退出碼 137 或 SIGKILL <a class="header-anchor" href="#退出碼-137-或-sigkill" aria-label="Permalink to “退出碼 137 或 SIGKILL”">​</a></h4><p><code>SIGKILL</code>（立即終止信號）表示終止信號 <code>9</code>。這是終止應用程序時最不應該使用的方法。</p><p>因為終止信號為 <code>9</code>，因此我們得到的退出代碼為 <code>137</code>（128+9）。</p><p><img src="https://itsfoss.com/content/media/2023/06/exit_code_128-n-SIGKILL-_compressed.mp4" alt=""></p><h4 id="退出碼-143-或-sigterm" tabindex="-1">退出碼 143 或 SIGTERM <a class="header-anchor" href="#退出碼-143-或-sigterm" aria-label="Permalink to “退出碼 143 或 SIGTERM”">​</a></h4><p><code>SIGTERM</code> 是進程在未指定參數的情況下被殺死時的默認行為。</p><p><code>SIGTERM</code> 的終止信號為 <code>15</code>，因此該信號的退出碼為 <code>143</code>（128+15）。</p><p><img src="https://itsfoss.com/content/media/2023/06/exit_code_128-n-SIGTERM-_compressed-1.mp4" alt=""></p><p>還有一些你以前可能不知道的終止信號，它們也有自己類似的退出碼。你可以在這裏查看它們：</p><blockquote><p>📋 請注意，如果進程在啓動它的同一會話中終止，這些信號可能不會出現。如果要重現這些信號，請從不同的 shell 終止。</p><p>就個人而言，信號 <code>128</code> 是無法重現的。</p></blockquote><h3 id="當退出碼超過了-255-會怎樣" tabindex="-1">當退出碼超過了 255 會怎樣? <a class="header-anchor" href="#當退出碼超過了-255-會怎樣" aria-label="Permalink to “當退出碼超過了 255 會怎樣?”">​</a></h3><p>最新版本的 Bash 甚至保留了超過 255 的原始退出碼的值，但一般來説，如果代碼超過 255，就會被重新計算。</p><p>也就是説，代碼 <code>256</code> 會變成 <code>0</code>，<code>257</code> 會變成 <code>1</code>，<code>383</code> 會變成 <code>127</code>，以此類推。為確保更好的兼容性，請將退出碼保持在 <code>0</code> 至 <code>255</code> 之間。</p><h3 id="結語" tabindex="-1">結語 <a class="header-anchor" href="#結語" aria-label="Permalink to “結語”">​</a></h3><p>希望你對 Linux Shell 中的退出碼有所瞭解。在排查各種問題時，使用它們會非常方便。</p><p>如果你要在 Shell 腳本中使用這些代碼，請確保你瞭解每個代碼的含義，以便更容易地排除故障。</p><p>這就是本文的全部內容。如有遺漏，請在評論區告訴我。</p><p><em>（題圖：MJ/719ff711-1b9f-4aa9-a82e-980704acbdd8）</em></p><hr>',28)),o("p",null,[t[30]||(t[30]=e("via: ",-1)),i(s,{href:"https://itsfoss.com/linux-exit-codes/"},{default:d(()=>[...t[29]||(t[29]=[e("https://itsfoss.com/linux-exit-codes/",-1)])]),_:1})]),o("p",null,[t[35]||(t[35]=e("作者：",-1)),i(s,{href:"https://itsfoss.com/author/pranav/"},{default:d(()=>[...t[31]||(t[31]=[e("Pranav Krishna",-1)])]),_:1}),t[36]||(t[36]=e(" 選題：",-1)),i(s,{href:"https://github.com/lkxed/"},{default:d(()=>[...t[32]||(t[32]=[e("lkxed",-1)])]),_:1}),t[37]||(t[37]=e(" 譯者：",-1)),i(s,{href:"https://github.com/lxbwolf"},{default:d(()=>[...t[33]||(t[33]=[e("lxbwolf",-1)])]),_:1}),t[38]||(t[38]=e(" 校對：",-1)),i(s,{href:"https://github.com/wxy"},{default:d(()=>[...t[34]||(t[34]=[e("wxy",-1)])]),_:1})]),o("p",null,[t[41]||(t[41]=e("本文由 ",-1)),i(s,{href:"https://github.com/LCTT/TranslateProject"},{default:d(()=>[...t[39]||(t[39]=[e("LCTT",-1)])]),_:1}),t[42]||(t[42]=e(" 原創編譯，",-1)),i(s,{href:"https://linux.cn/"},{default:d(()=>[...t[40]||(t[40]=[e("Linux中國",-1)])]),_:1}),t[43]||(t[43]=e(" 榮譽推出",-1))])])}const S=a(c,[["render",g]]);export{T as __pageData,S as default};
